#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Ω·m".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::OhmMeter)
    );
    assert_eq!(
        format!("2.5 {}", "Ω·m").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::OhmMeter
        ))
    );
    assert_eq!(
        "pΩ·m".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::PicoohmMeter)
    );
    assert_eq!(
        format!("2.5 {}", "pΩ·m").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::PicoohmMeter
        ))
    );
    assert_eq!(
        "nΩ·m".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::NanoohmMeter)
    );
    assert_eq!(
        format!("2.5 {}", "nΩ·m").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::NanoohmMeter
        ))
    );
    assert_eq!(
        "µΩ·m".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::MicroohmMeter)
    );
    assert_eq!(
        format!("2.5 {}", "µΩ·m").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::MicroohmMeter
        ))
    );
    assert_eq!(
        "mΩ·m".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::MilliohmMeter)
    );
    assert_eq!(
        format!("2.5 {}", "mΩ·m").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::MilliohmMeter
        ))
    );
    assert_eq!(
        "kΩ·m".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::KiloohmMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kΩ·m").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::KiloohmMeter
        ))
    );
    assert_eq!(
        "MΩ·m".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::MegaohmMeter)
    );
    assert_eq!(
        format!("2.5 {}", "MΩ·m").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::MegaohmMeter
        ))
    );
    assert_eq!(
        "Ω·cm".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::OhmCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "Ω·cm").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::OhmCentimeter
        ))
    );
    assert_eq!(
        "pΩ·cm".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::PicoohmCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "pΩ·cm").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::PicoohmCentimeter
        ))
    );
    assert_eq!(
        "nΩ·cm".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::NanoohmCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "nΩ·cm").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::NanoohmCentimeter
        ))
    );
    assert_eq!(
        "µΩ·cm".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::MicroohmCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "µΩ·cm").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::MicroohmCentimeter
        ))
    );
    assert_eq!(
        "mΩ·cm".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::MilliohmCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "mΩ·cm").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::MilliohmCentimeter
        ))
    );
    assert_eq!(
        "kΩ·cm".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::KiloohmCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "kΩ·cm").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::KiloohmCentimeter
        ))
    );
    assert_eq!(
        "MΩ·cm".parse::<ElectricResistivityUnit>(),
        Ok(ElectricResistivityUnit::MegaohmCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "MΩ·cm").parse::<ElectricResistivity>(),
        Ok(ElectricResistivity::new(
            2.5,
            ElectricResistivityUnit::MegaohmCentimeter
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricResistivity>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricResistivity::from_base(6.0);
    let b = ElectricResistivity::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricResistivity::<i64>::from_base(7);
    let b = ElectricResistivity::<i64>::from_base(2);
    assert_eq!(a + b, ElectricResistivity::from_base(9));
    assert_eq!(a % b, ElectricResistivity::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricResistivity<i64>>(),
        ElectricResistivity::from_base(9)
    );
}
